fn call_from_statement(stmt: &AnyJsStatement) -> Option<JsCallExpression> {
    let expr_stmt = stmt.as_js_expression_statement()?;
    let expr = expr_stmt.expression().ok()?;
    expr.as_js_call_expression().cloned()
}

